tool_input.old_string:
companyId() {
  return this.tempAccountInfo?.companyId || this.$route.query.companyId || this.$route.query.id || this.$route.params.applyId
},

tool_input.new_string:
companyId() {
  const routeApplyId = this.$route.params.applyId
  const validRouteApplyId = routeApplyId && String(routeApplyId).toLowerCase() !== 'add' ? routeApplyId : undefined
  return this.tempAccountInfo?.companyId || this.$route.query.companyId || this.$route.query.id || validRouteApplyId
},
